DROP TABLE IF EXISTS dbc.dbc_liquidtype;

CREATE TABLE dbc.dbc_liquidtype
(
    id                 integer PRIMARY KEY DEFAULT 0,
    name               text,
    flags              integer NOT NULL    DEFAULT 0,
    type               integer NOT NULL    DEFAULT 0,
    soundid            integer NOT NULL    DEFAULT 0,
    spellid            integer NOT NULL    DEFAULT 0,
    maxdarkendepth     float4  NOT NULL    DEFAULT 0,
    fogdarkenintensity float4  NOT NULL    DEFAULT 0,
    ambdarkenintensity float4  NOT NULL    DEFAULT 0,
    dirdarkenintensity float4  NOT NULL    DEFAULT 0,
    lightid            integer NOT NULL    DEFAULT 0,
    particlescale      float4  NOT NULL    DEFAULT 0,
    particlemovement   integer NOT NULL    DEFAULT 0,
    particletexslots   integer NOT NULL    DEFAULT 0,
    materialid         integer NOT NULL    DEFAULT 0,
    texture_1          text,
    texture_2          text,
    texture_3          text,
    texture_4          text,
    texture_5          text,
    texture_6          text,
    color_1            integer NOT NULL    DEFAULT 0,
    color_2            integer NOT NULL    DEFAULT 0,
    float_1            float4  NOT NULL    DEFAULT 0,
    float_2            float4  NOT NULL    DEFAULT 0,
    float_3            float4  NOT NULL    DEFAULT 0,
    float_4            float4  NOT NULL    DEFAULT 0,
    float_5            float4  NOT NULL    DEFAULT 0,
    float_6            float4  NOT NULL    DEFAULT 0,
    float_7            float4  NOT NULL    DEFAULT 0,
    float_8            float4  NOT NULL    DEFAULT 0,
    float_9            float4  NOT NULL    DEFAULT 0,
    float_10           float4  NOT NULL    DEFAULT 0,
    float_11           float4  NOT NULL    DEFAULT 0,
    float_12           float4  NOT NULL    DEFAULT 0,
    float_13           float4  NOT NULL    DEFAULT 0,
    float_14           float4  NOT NULL    DEFAULT 0,
    float_15           float4  NOT NULL    DEFAULT 0,
    float_16           float4  NOT NULL    DEFAULT 0,
    float_17           float4  NOT NULL    DEFAULT 0,
    float_18           float4  NOT NULL    DEFAULT 0,
    int_1              integer NOT NULL    DEFAULT 0,
    int_2              integer NOT NULL    DEFAULT 0,
    int_3              integer NOT NULL    DEFAULT 0,
    int_4              integer NOT NULL    DEFAULT 0
);

